import re

def parse_duration(s):
    s = s.strip().lower()
    if not s:
        raise ValueError('Invalid input: empty string')

    # Check for colon format (hh:mm:ss or mm:ss)
    if ':' in s:
        parts = s.split(':')
        if len(parts) == 2:  # mm:ss
            try:
                minutes, seconds = map(int, parts)
                return minutes * 60 + seconds
            except ValueError:
                raise ValueError('Invalid input: colon format mm:ss')
        elif len(parts) == 3:  # hh:mm:ss
            try:
                hours, minutes, seconds = map(int, parts)
                return hours * 3600 + minutes * 60 + seconds
            except ValueError:
                raise ValueError('Invalid input: colon format hh:mm:ss')
        else:
            raise ValueError('Invalid input: too many colons')

    # Match concatenated units
    pattern = r'(?:(\d+(?:\.\d+)?)([hms]))'
    matches = re.findall(pattern, s)
    if matches:
        total_seconds = 0
        for value, unit in matches:
            try:
                value = float(value)
                if unit == 'h':
                    total_seconds += int(value * 3600)
                elif unit == 'm':
                    total_seconds += int(value * 60)
                elif unit == 's':
                    total_seconds += int(value)
            except ValueError:
                raise ValueError('Invalid input: unit parsing failed')
        return total_seconds

    # Match bare number
    try:
        return int(float(s))
    except ValueError:
        raise ValueError('Invalid input: bare number parsing failed')

